workflowLoops.body:
foreach ($exe in Get-ChildItem dist-electron/*.exe) {
  node scripts/ci/release-receipt-workflow.mjs authenticode-pre $exe.FullName evidence/authenticode
  if ($LASTEXITCODE -ne 0) { throw "independent pre-upload verification failed: $($exe.Name)" }
}

foreach ($exe in Get-ChildItem post-download/*.exe) {
  node scripts/ci/release-receipt-workflow.mjs authenticode-post $exe.FullName evidence/authenticode
  if ($LASTEXITCODE -ne 0) { throw "independent post-download verification failed: $($exe.Name)" }
}
Copy-Item evidence/authenticode/*.json post-download/evidence/authenticode/ -Force

$identity = "https://github.com/${{ github.repository }}/.github/workflows/reusable-windows-qualification.yml@${{ github.ref }}"
$results = @()
foreach ($exe in Get-ChildItem post-download/*.exe) {
  node scripts/ci/release-receipt-workflow.mjs capture-attestation $exe.FullName "${{ inputs.subject_sha }}" .github/workflows/reusable-windows-qualification.yml evidence/current-attestation.json
  if ($LASTEXITCODE -ne 0) { throw "gh verification failed: $($exe.Name)" }
  $results += @(Get-Content evidence/current-attestation.json | ConvertFrom-Json)
}
ConvertTo-Json -InputObject $results -Depth 100 | Out-File -Encoding utf8 evidence/attestation-verification.json
node scripts/ci/release-receipt-workflow.mjs attestation-windows evidence/attestation-verification.json "${{ inputs.subject_sha }}" "${{ inputs.client_digest }}" $identity
if ($LASTEXITCODE -ne 0) { throw 'attestation normalization failed' }
